-- Check how many unique accounts are in security_sessions but NOT in monitoring
SELECT COUNT(*) FROM security_sessions ss 
WHERE NOT EXISTS (SELECT 1 FROM monitoring m WHERE m."acct_mon" = ss.acct_gate);

SELECT COUNT(*) FROM security_sessions ss 
WHERE CAST(regexp_replace(ss.session_telemetry->>'vpn_usage_pct', '[^0-9.]', '', 'g') AS numeric) > 0.5
AND NOT EXISTS (SELECT 1 FROM monitoring m WHERE m."acct_mon" = ss.acct_gate);

SELECT COUNT(*) FROM security_sessions ss 
WHERE CAST(regexp_replace(ss.session_telemetry->>'vpn_usage_pct', '[^0-9.]', '', 'g') AS numeric) > 0.5
AND NOT EXISTS (SELECT 1 FROM monitoring m WHERE m."acct_mon" = ss.acct_gate);

-- Check how many accounts have vpn_usage_pct >= 0.8 (80%)
SELECT COUNT(*) FROM security_sessions 
WHERE CAST(regexp_replace(session_telemetry->>'vpn_usage_pct', '[^0-9.]', '', 'g') AS numeric) >= 0.8;

SELECT COUNT(*) FROM security_sessions ss 
WHERE session_telemetry->>'vpn_usage_pct' = '1.00%'
AND NOT EXISTS (SELECT 1 FROM monitoring m WHERE m."acct_mon" = ss.acct_gate);

SELECT COUNT(*) as new_items FROM (
  SELECT ss.acct_gate 
  FROM security_sessions ss 
  WHERE NOT EXISTS (SELECT 1 FROM monitoring m WHERE m."acct_mon" = ss.acct_gate)
) sub;

SELECT COUNT(*) FROM security_sessions ss 
WHERE ss.session_telemetry->'ip_reputation'->>'tor_flag' = 'Yes'
AND NOT EXISTS (SELECT 1 FROM monitoring m WHERE m."acct_mon" = ss.acct_gate);

SELECT COUNT(*) as new_watch_items_added FROM (
  SELECT ss.acct_gate 
  FROM security_sessions ss 
  WHERE CAST(regexp_replace(ss.session_telemetry->>'vpn_usage_pct', '[^0-9.]', '', 'g') AS numeric) > 0.5
  AND NOT EXISTS (SELECT 1 FROM monitoring m WHERE m."acct_mon" = ss.acct_gate)
) sub;

SELECT COUNT(*) FROM security_sessions 
WHERE session_telemetry->'ip_reputation'->>'tor_flag' = 'Yes'
AND CAST(regexp_replace(session_telemetry->>'vpn_usage_pct', '[^0-9.]', '', 'g') AS numeric) > 0;

SELECT COUNT(*) FROM security_sessions 
WHERE session_telemetry->'ip_reputation'->>'tor_flag' = 'Yes'
AND CAST(regexp_replace(session_telemetry->>'vpn_usage_pct', '[^0-9.]', '', 'g') AS numeric) > 0;
